export const envelope = [36, 12, 14];

export default function build(api) {
  const [W, H, D] = api.size;
  const grid = new Map();

  function key(x, y, z) {
    return `${x},${y},${z}`;
  }

  function inBounds(x, y, z) {
    return x >= 0 && x < W && y >= 0 && y < H && z >= 0 && z < D;
  }

  function setBlock(x, y, z, block) {
    x = Math.floor(x);
    y = Math.floor(y);
    z = Math.floor(z);
    if (inBounds(x, y, z)) {
      grid.set(key(x, y, z), block);
    }
  }

  function getBlock(x, y, z) {
    return grid.get(key(Math.floor(x), Math.floor(y), Math.floor(z))) || null;
  }

  // --- Palette & Block States ---
  const wood = api.theme.wood || {};
  const ground = api.theme.ground || {};
  const stone = api.theme.stone || {};

  function withState(b, s) {
    if (!b) return s;
    const base = b.split("[")[0];
    return `${base}[${s}]`;
  }

  const rawLog = wood.log || "minecraft:spruce_log";
  const rawStripped = wood.stripped || wood.log || "minecraft:stripped_spruce_log";
  const rawPlanks = wood.planks || "minecraft:spruce_planks";
  const rawSlab = wood.slab || "minecraft:spruce_slab";
  const rawStairs = wood.stairs || "minecraft:spruce_stairs";
  const rawFence = wood.fence || "minecraft:spruce_fence";
  const rawTrapdoor = wood.trapdoor || "minecraft:spruce_trapdoor";

  const logX = withState(rawLog, "axis=x");
  const logY = withState(rawLog, "axis=y");
  const logZ = withState(rawLog, "axis=z");

  const strippedX = withState(rawStripped, "axis=x");
  const strippedY = withState(rawStripped, "axis=y");
  const strippedZ = withState(rawStripped, "axis=z");

  const planks = rawPlanks;
  const slabBottom = withState(rawSlab, "type=bottom");
  const slabTop = withState(rawSlab, "type=top");

  const stairsN = withState(rawStairs, "facing=north,half=bottom,shape=straight");
  const stairsS = withState(rawStairs, "facing=south,half=bottom,shape=straight");
  const stairsW = withState(rawStairs, "facing=west,half=bottom,shape=straight");
  const stairsTopN = withState(rawStairs, "facing=north,half=top,shape=straight");
  const stairsTopS = withState(rawStairs, "facing=south,half=top,shape=straight");

  const trapdoorFloor = withState(rawTrapdoor, "facing=north,half=bottom,open=false");
  const fence = rawFence;

  const plinth = ground.plinth || stone.primary || "minecraft:stone_bricks";
  const scree = ground.scree || ground.pavement || "minecraft:coarse_dirt";
  const stoneSlab = stone.slab || "minecraft:stone_slab";

  const chainY = "minecraft:chain[axis=y]";
  const chainX = "minecraft:chain[axis=x]";
  const chainZ = "minecraft:chain[axis=z]";
  const ironBarsZ = "minecraft:iron_bars[north=true,south=true]";
  const lanternFloor = "minecraft:lantern[hanging=false]";
  const lanternHang = "minecraft:lantern[hanging=true]";
  const ladderW = "minecraft:ladder[facing=west]";

  function groundColumn(x, z, startY, block) {
    const h = api.heightAt(x, z);
    const bottomY = Math.max(0, Math.min(startY, h));
    for (let y = startY; y >= bottomY; y--) {
      if (!getBlock(x, y, z)) {
        setBlock(x, y, z, block);
      }
    }
  }

  // --- 1. Skid Bunks (Cross timbers under the giant tree) ---
  const skidPositions = [5, 12, 19, 26, 32];
  for (const sx of skidPositions) {
    for (let z = 2; z <= 11; z++) {
      setBlock(sx, 1, z, logZ);
      groundColumn(sx, z, 0, plinth);
    }
    // Skid chocks to prevent roll
    setBlock(sx, 2, 3, stairsS);
    setBlock(sx, 2, 10, stairsN);

    // Retaining stake posts at the ends of skids
    setBlock(sx, 1, 2, logY);
    setBlock(sx, 2, 2, fence);
    setBlock(sx, 1, 11, logY);
    setBlock(sx, 2, 11, fence);
  }

  // Double bunks under saw and bucking zones
  for (let z = 3; z <= 10; z++) {
    setBlock(13, 1, z, logZ);
    groundColumn(13, z, 0, plinth);
    setBlock(20, 1, z, logZ);
    groundColumn(20, z, 0, plinth);
  }

  // --- 2. The Colossal Redwood Trunk Geometry ---
  for (let x = 2; x <= 33; x++) {
    const t = (x - 2) / 31.0;
    const cy = 5.2 - 0.7 * t;
    const cz = 6.6 + 0.25 * Math.sin(t * Math.PI * 1.5);
    const baseR = 3.35 * (1.0 - 0.36 * t);

    // Buttress flare & fluting at the butt end
    const flare = Math.max(0, 1.0 - (x - 2) / 7.0);

    const minZ = Math.max(0, Math.floor(cz - baseR * 1.6));
    const maxZ = Math.min(D - 1, Math.ceil(cz + baseR * 1.6));
    const minY = Math.max(1, Math.floor(cy - baseR * 1.6));
    const maxY = Math.min(H - 1, Math.ceil(cy + baseR * 1.6));

    for (let y = minY; y <= maxY; y++) {
      for (let z = minZ; z <= maxZ; z++) {
        const dy = y - cy;
        const dz = z - cz;
        const angle = Math.atan2(dz, dy);
        const flute = flare * (0.50 * Math.cos(4 * angle) + 0.30 * Math.sin(3 * angle + 0.4));
        const effectiveR = baseR * (1.0 + flute);
        const dist = Math.hypot(dy, dz);

        if (dist <= effectiveR) {
          const isEndFace = (x === 2 || x === 33);
          const isOuter = (dist >= effectiveR - 0.82);

          if (isEndFace) {
            // Cut face showing annual growth rings & heartwood
            if (dist < effectiveR - 0.7) {
              setBlock(x, y, z, (dist < 1.2) ? planks : strippedX);
            } else {
              setBlock(x, y, z, logX);
            }
          } else {
            // Solid log body
            if (isOuter) {
              if (dy > 1.2 && dist >= effectiveR - 0.4 && (x + z) % 7 === 0) {
                setBlock(x, y, z, strippedX); // Peeled bark patch
              } else {
                setBlock(x, y, z, logX);
              }
            } else {
              setBlock(x, y, z, ((x + y + z) % 5 === 0) ? strippedX : logX);
            }
          }
        }
      }
    }
  }

  // --- 3. Undercut Felling Notch & Saw Kerf ---
  // A. Carve the triangular undercut notch on North face (X = 15, 16)
  for (let x = 15; x <= 16; x++) {
    for (let y = 3; y <= 9; y++) {
      for (let z = 2; z <= 12; z++) {
        const t = (x - 2) / 31.0;
        const cy = 5.2 - 0.7 * t;
        const cz = 6.6 + 0.25 * Math.sin(t * Math.PI * 1.5);

        if (z <= cz + 0.2 && y >= cy - 0.4) {
          const depthFromNorth = (cz + 0.2) - z;
          const heightAboveFloor = y - (cy - 0.4);

          if (heightAboveFloor <= depthFromNorth * 1.15 + (x === 16 ? 0.9 : 0.0)) {
            grid.delete(key(x, y, z));
          }
        }
      }
    }
  }

  // Notch interior floor & hewn axe-cut roof
  for (let x = 15; x <= 16; x++) {
    const t = (x - 2) / 31.0;
    const cy = 5.2 - 0.7 * t;
    const floorY = Math.floor(cy);
    for (let z = 4; z <= 7; z++) {
      if (!getBlock(x, floorY, z) && getBlock(x, floorY - 1, z)) {
        setBlock(x, floorY, z, (z === 6 || z === 7) ? slabBottom : strippedX);
      }
      const roofY = floorY + Math.max(1, Math.floor((7 - z) * 0.9));
      if (roofY < H && !getBlock(x, roofY, z) && getBlock(x, roofY + 1, z)) {
        setBlock(x, roofY, z, stairsTopS);
      }
    }
  }

  // B. The Backcut & Two-Man Saw Blade (at X = 18)
  const sawY = Math.floor(5.2 - 0.7 * (16 / 31.0));
  for (let z = 3; z <= 10; z++) {
    setBlock(18, sawY, z, ironBarsZ);
  }
  // Upright wooden handles for the two sawyers
  setBlock(18, sawY + 1, 3, fence);
  setBlock(18, sawY + 2, 3, fence);
  setBlock(18, sawY + 1, 10, fence);
  setBlock(18, sawY + 2, 10, fence);

  // Split timber wedges driven into back cut to prevent pinch
  setBlock(18, sawY + 2, 8, stairsTopN);
  setBlock(18, sawY + 2, 9, slabTop);
  setBlock(17, sawY + 2, 8, slabTop);
  setBlock(19, sawY + 3, 7, stoneSlab); // Sledgehammer resting on top of trunk

  // --- 4. Springboards (Sawyers' standing planks at the butt) ---
  setBlock(4, 4, 3, strippedX);
  setBlock(4, 4, 2, slabTop);
  setBlock(4, 4, 1, slabTop);
  setBlock(4, 3, 2, chainY);

  setBlock(6, 5, 10, strippedX);
  setBlock(6, 5, 11, slabTop);
  setBlock(6, 5, 12, slabTop);
  setBlock(6, 4, 11, chainY);

  // --- 5. Rough Timber Staging & Platforms ---
  // North Platform (Z = 1..3, X = 13..21, Y = 4)
  const northPosts = [13, 17, 21];
  for (const px of northPosts) {
    for (let y = 0; y <= 4; y++) {
      setBlock(px, y, 1, logY);
    }
    groundColumn(px, 1, 0, plinth);

    for (let y = 1; y <= 4; y++) {
      if (!getBlock(px, y, 3)) setBlock(px, y, 3, logY);
    }
    groundColumn(px, 3, 0, plinth);
  }

  for (let x = 13; x <= 21; x++) {
    setBlock(x, 4, 1, logX);
    for (let z = 2; z <= 3; z++) {
      if (!getBlock(x, 4, z)) {
        setBlock(x, 4, z, planks);
      }
    }
  }

  for (let x = 14; x <= 20; x++) {
    if (x !== 18) {
      setBlock(x, 5, 1, fence);
    }
  }
  setBlock(13, 5, 1, fence);
  setBlock(13, 6, 1, fence);
  setBlock(13, 6, 2, slabTop);
  setBlock(13, 5, 2, lanternHang);

  setBlock(21, 5, 2, planks);
  setBlock(21, 6, 2, trapdoorFloor);
  setBlock(20, 5, 3, lanternFloor);

  for (let y = 1; y <= 4; y++) {
    setBlock(22, y, 1, ladderW);
  }

  // South Platform (Z = 10..12, X = 15..22, Y = 4)
  const southPosts = [15, 18, 22];
  for (const px of southPosts) {
    for (let y = 0; y <= 4; y++) {
      setBlock(px, y, 12, logY);
    }
    groundColumn(px, 12, 0, plinth);

    for (let y = 1; y <= 4; y++) {
      if (!getBlock(px, y, 10)) setBlock(px, y, 10, logY);
    }
    groundColumn(px, 10, 0, plinth);
  }

  for (let x = 15; x <= 22; x++) {
    setBlock(x, 4, 12, logX);
    for (let z = 10; z <= 11; z++) {
      if (!getBlock(x, 4, z)) {
        setBlock(x, 4, z, planks);
      }
    }
  }

  for (let x = 15; x <= 21; x++) {
    if (x !== 18) {
      setBlock(x, 5, 12, fence);
    }
  }
  setBlock(16, 5, 11, lanternFloor);

  setBlock(23, 3, 11, stairsW);
  setBlock(23, 2, 11, planks);
  setBlock(24, 2, 11, stairsW);
  setBlock(24, 1, 11, planks);
  setBlock(25, 1, 11, stairsW);
  groundColumn(23, 11, 1, plinth);
  groundColumn(24, 11, 0, plinth);
  groundColumn(25, 11, 0, plinth);

  // --- 6. Heavy Rigging & Choker Cables ---
  const chokerT = (28 - 2) / 31.0;
  const chokerCy = 5.2 - 0.7 * chokerT;
  const chokerCz = 6.6 + 0.25 * Math.sin(chokerT * Math.PI * 1.5);
  const chokerR = 3.35 * (1.0 - 0.36 * chokerT);

  for (let y = 1; y <= 9; y++) {
    for (let z = 2; z <= 11; z++) {
      const dist = Math.hypot(y - chokerCy, z - chokerCz);
      if (dist >= chokerR - 0.15 && dist <= chokerR + 0.85) {
        if (!getBlock(28, y, z)) {
          const isVertical = Math.abs(z - chokerCz) > Math.abs(y - chokerCy);
          setBlock(28, y, z, isVertical ? chainY : chainZ);
        }
      }
    }
  }

  const topY = Math.ceil(chokerCy + chokerR);
  setBlock(28, topY, Math.round(chokerCz), chainX);
  setBlock(29, topY, Math.round(chokerCz), chainX);
  setBlock(30, topY, Math.round(chokerCz), chainX);

  // --- 7. Burls, Sawn Stubs & Cookie Rounds ---
  setBlock(9, 9, 6, logY);
  setBlock(9, 10, 6, logY);
  setBlock(9, 10, 7, strippedY);

  setBlock(24, 7, 9, logZ);
  setBlock(24, 7, 10, strippedZ);

  setBlock(31, 4, 4, logZ);
  setBlock(31, 4, 3, strippedZ);

  // Sawn cookie round standing at butt
  for (let y = 1; y <= 4; y++) {
    for (let z = 8; z <= 10; z++) {
      const cDist = Math.hypot(y - 2.5, z - 9.0);
      if (cDist <= 1.6) {
        setBlock(1, y, z, (cDist < 1.0) ? strippedX : logX);
        setBlock(0, y, z, (cDist < 1.0) ? planks : logX);
      }
    }
  }
  setBlock(1, 1, 7, stairsS);
  setBlock(1, 1, 11, stairsN);
  groundColumn(1, 8, 0, plinth);
  groundColumn(1, 9, 0, plinth);
  groundColumn(1, 10, 0, plinth);

  // Split timber shingle bolt stack
  setBlock(0, 1, 3, slabBottom);
  setBlock(0, 1, 4, slabBottom);
  setBlock(1, 1, 3, slabTop);
  setBlock(1, 1, 4, slabTop);
  setBlock(0, 2, 3, slabBottom);
  setBlock(0, 2, 4, slabBottom);
  groundColumn(0, 3, 0, plinth);
  groundColumn(0, 4, 0, plinth);

  // --- 8. Sawdust Drifts, Peeled Bark & Skid Chute Runners ---
  for (let x = 14; x <= 19; x++) {
    for (let z = 4; z <= 9; z++) {
      if (!getBlock(x, 1, z)) {
        setBlock(x, 1, z, ((x + z) % 3 === 0) ? slabBottom : scree);
      }
    }
  }

  setBlock(8, 1, 2, trapdoorFloor);
  setBlock(9, 1, 2, trapdoorFloor);
  setBlock(10, 1, 2, slabBottom);
  setBlock(24, 1, 11, trapdoorFloor);
  setBlock(25, 1, 11, slabBottom);

  for (let x = 33; x <= 35; x++) {
    setBlock(x, 1, 5, logX);
    setBlock(x, 1, 8, logX);
    setBlock(x, 1, 6, scree);
    setBlock(x, 1, 7, scree);
    groundColumn(x, 5, 0, plinth);
    groundColumn(x, 8, 0, plinth);
    groundColumn(x, 6, 0, plinth);
    groundColumn(x, 7, 0, plinth);
  }

  // --- 9. Final Grounding Pass ---
  for (let x = 0; x < W; x++) {
    for (let z = 0; z < D; z++) {
      let lowestY = -1;
      for (let y = 0; y < H; y++) {
        if (getBlock(x, y, z)) {
          lowestY = y;
          break;
        }
      }
      if (lowestY >= 1) {
        const h = api.heightAt(x, z);
        const targetMin = Math.min(0, h);
        for (let y = lowestY - 1; y >= targetMin; y--) {
          if (!getBlock(x, y, z)) {
            setBlock(x, y, z, plinth);
          }
        }
      }
    }
  }

  // --- 10. Write Grid to World ---
  for (let x = 0; x < W; x++) {
    for (let y = 0; y < H; y++) {
      for (let z = 0; z < D; z++) {
        const b = getBlock(x, y, z);
        if (b) {
          api.set(x, y, z, b);
        }
      }
    }
  }

  return {
    name: "Colossal Felled Redwood",
    seatY: 0,
    anchors: {
      front: [18, 5, 0],
      butt: [2, 5, 7],
      staging_north: [17, 4, 1],
      staging_south: [18, 4, 12],
      skid_trail: [35, 1, 7],
    },
  };
}
